package inventory

import "sort"

// ReorderAt 是需要补货的数量阈值：Qty 严格低于它才需要补货。
const ReorderAt = 5

// Item 是库存里的一条记录。
type Item struct {
	SKU string
	Qty int
}

// Stock 返回某个 SKU 的数量；没有这个 SKU 时返回 0。
func Stock(items []Item, sku string) int {
	for _, it := range items {
		if it.SKU == sku {
			return it.Qty
		}
	}
	return 0
}

// Reorder 返回需要补货（Qty < ReorderAt）的条目，按 Qty 升序排列，
// Qty 相同时按 SKU 升序；不修改传入的切片。
func Reorder(items []Item) []Item {
	out := make([]Item, 0, len(items))
	for _, it := range items {
		if it.Qty < ReorderAt {
			out = append(out, it)
		}
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].Qty != out[j].Qty {
			return out[i].Qty < out[j].Qty
		}
		return out[i].SKU < out[j].SKU
	})
	return out
}
