package inventory

import (
	"reflect"
	"testing"
)

func TestReorderAt(t *testing.T) {
	if ReorderAt != 5 {
		t.Fatalf("ReorderAt = %d，想要 5", ReorderAt)
	}
}

func TestReorderEmpty(t *testing.T) {
	got := Reorder(nil)
	if len(got) != 0 {
		t.Fatalf("Reorder(nil) = %v，想要零长结果", got)
	}
	got = Reorder([]Item{})
	if len(got) != 0 {
		t.Fatalf("Reorder([]) = %v，想要零长结果", got)
	}
}

func TestReorderFilters(t *testing.T) {
	items := []Item{
		{SKU: "boundary", Qty: 5}, // 严格小于阈值，不应出现
		{SKU: "high", Qty: 9},
		{SKU: "zero", Qty: 0},
	}
	got := Reorder(items)
	want := []Item{{SKU: "zero", Qty: 0}}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("Reorder() = %v，想要 %v", got, want)
	}
}

func TestReorderSortsByQtyThenSKU(t *testing.T) {
	items := []Item{
		{SKU: "b", Qty: 3},
		{SKU: "a", Qty: 3},
		{SKU: "z", Qty: 1},
		{SKU: "skip", Qty: 5},
		{SKU: "c", Qty: 4},
	}
	got := Reorder(items)
	want := []Item{
		{SKU: "z", Qty: 1},
		{SKU: "a", Qty: 3},
		{SKU: "b", Qty: 3},
		{SKU: "c", Qty: 4},
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("Reorder() = %v，想要 %v", got, want)
	}
}

func TestReorderDoesNotMutateInput(t *testing.T) {
	items := []Item{
		{SKU: "b", Qty: 3},
		{SKU: "a", Qty: 1},
		{SKU: "c", Qty: 4},
	}
	snapshot := make([]Item, len(items))
	copy(snapshot, items)

	got := Reorder(items)
	if !reflect.DeepEqual(items, snapshot) {
		t.Fatalf("Reorder 修改了入参：%v，原本 %v", items, snapshot)
	}

	// 返回的切片应独立于入参。
	if len(got) > 0 {
		got[0].Qty = 999
		if items[1] == got[0] {
			t.Fatalf("Reorder 的返回切片与入参共享底层数组")
		}
	}
}
