package pricing

// BulkTotal 返回一批货按折扣后的金额（单位：分）。
// 折扣为 discountPct 百分比，按 Go 整数除法向下取整。
func BulkTotal(cents, qty, discountPct int) int {
	total := Total(cents, qty)
	return total - total*discountPct/100
}
