package pricing

import "testing"

func TestBulkTotal(t *testing.T) {
	cases := []struct {
		name        string
		cents, qty  int
		discountPct int
		want        int
	}{
		{"no discount", 250, 3, 0, 750},
		{"ten percent", 250, 4, 10, 900},
		{"full discount", 250, 3, 100, 0},
		{"truncates toward zero", 101, 1, 33, 68}, // 101*33/100 = 33（截断）
		{"zero qty", 250, 0, 20, 0},
		{"zero cents", 0, 5, 20, 0},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := BulkTotal(tc.cents, tc.qty, tc.discountPct); got != tc.want {
				t.Fatalf("BulkTotal(%d, %d, %d) = %d，想要 %d",
					tc.cents, tc.qty, tc.discountPct, got, tc.want)
			}
		})
	}
}

// 确认 BulkTotal 复用 Total 的金额定义。
func TestBulkTotalUsesTotal(t *testing.T) {
	if got := BulkTotal(250, 3, 50); got != Total(250, 3)/2 {
		t.Fatalf("BulkTotal(250, 3, 50) = %d，想要 %d", got, Total(250, 3)/2)
	}
}

