package report

import (
	"reflect"
	"testing"

	"example.com/shop/inventory"
)

func TestLowStockLinesOrderAndAmounts(t *testing.T) {
	items := []inventory.Item{
		{SKU: "A", Qty: 3},
		{SKU: "C", Qty: 7}, // 不需要补货，不应出现
		{SKU: "B", Qty: 2},
		{SKU: "D", Qty: 2}, // 不在 unitCents 里，按 0 分计
	}
	unitCents := map[string]int{
		"A": 100,
		"B": 50,
		"C": 999,
	}

	got := LowStockLines(items, unitCents, 10)
	want := []string{
		"B x2 = 90",  // 50*2=100，折扣 10% 后 90
		"D x2 = 0",   // 缺 SKU，按 0 分计
		"A x3 = 270", // 100*3=300，折扣 10% 后 270
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("LowStockLines = %q, want %q", got, want)
	}
}

func TestLowStockLinesDiscountFloors(t *testing.T) {
	items := []inventory.Item{{SKU: "A", Qty: 1}}
	unitCents := map[string]int{"A": 333}

	// 333*10/100 = 33.3，整数向下取整为 33，金额 300。
	got := LowStockLines(items, unitCents, 10)
	want := []string{"A x1 = 300"}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("LowStockLines = %q, want %q", got, want)
	}
}

func TestLowStockLinesEmpty(t *testing.T) {
	got := LowStockLines(nil, nil, 0)
	if len(got) != 0 {
		t.Fatalf("LowStockLines(nil) = %q, want empty", got)
	}
}
